  const traits=Array.from({length:4},(_,q)=>{
    const {sym,col}=previewSpinTrait(q,Math.floor(Math.random()*8),Math.floor(Math.random()*8));
    return [q,sym,col];
  });
  applyDgnTicketAccent(card,traits.map(([q,s,c])=>(q<<6)|(c<<3)|s));
  for(const [q,s,c] of traits){const cell=document.createElement('span');cell.className='trait-quadrant';if(c===7)cell.classList.add('trait-quadrant--gold');const img=document.createElement('img');img.src=issuedTicketBadgePath(q,s,c);img.alt='';cell.append(img);card.append(cell);}
