function syncKey(){
  if(!desktop.matches)return;
  const key=buy.querySelector('[data-bind="reveal-btn"]');if(!key)return;
  const native=draw.querySelector('[data-bind="reveal-btn"]');
  const ready=Boolean(native&&!native.hidden&&!native.disabled&&/spin jackpot/i.test(native.textContent));
  native?.classList.toggle('concept-ready',ready);
  machine.toggleAttribute('data-jackpot-pending',ready);
  if(ready&&!wasReady){
    wasReady=true;
    if(face==='buy'&&!matchMedia('(prefers-reduced-motion:reduce)').matches){
      buy.querySelector('[data-bind="card-grid"]')?.classList.add('site-board-leaving');
      readyTimer=setTimeout(()=>{if(wasReady)show('draw');},240);
    }else show('draw');
  }
  if(!ready&&wasReady){clearTimeout(readyTimer);buy.querySelector('[data-bind="card-grid"]')?.classList.remove('site-board-leaving');}
  wasReady=ready;
  const game=get('app.gameState');
  // The native board owns the reset-to-spin handoff. During that handoff,
  // tomorrow's reset timer must not replace today's pending jackpot.
  const loading=!ready&&(['processing','mine-flip'].includes(native?.dataset.replayAction)
    ||draw.hasAttribute('data-day-warming')||draw.hasAttribute('data-day-loading'));
  const mine=document.querySelector('.info-rail [data-mine-flip]');
  const minable=Boolean(mine&&!mine.disabled);
  const pending=!loading&&native&&!native.hidden&&(ready||['reveal','bonus','reveal-results','decimator','coinflip','craps-battle','unavailable'].includes(native.dataset.replayAction));
  const waiting=!loading&&!pending&&!minable&&game?.gameOver!==true;
  const ticket=buy.querySelector('[data-dgx-kind="tickets"]');
  const buyNow=waiting&&ticket&&!ticket.disabled;
  const action=pending?'draw':minable?'mine':buyNow?'tickets':'';
  const visible=loading||pending||minable||waiting;
  key.classList.toggle('concept-key-idle',!visible);
  key.classList.toggle('site-mine-ready',action==='mine');
  key.classList.toggle('site-buy-ready',action==='tickets');
  key.dataset.hubAction=action;
  const heading=loading?'JACKPOT LOADING':`NEXT JACKPOT IN ${formatHubJackpotCountdown(secondsUntilDayCrossover())}`;
  const text=pending?native.textContent:visible?`${heading}${minable?' · MINE FLIP':waiting?' · BUY IN NOW':''}`:'';
  if(key.textContent!==text)key.textContent=text;
  key.disabled=!action;
  key.setAttribute('aria-label',text||'Next jackpot');
  key.title=text||'Next jackpot';
}
