const segments=['abcdef','bc','abged','abcdg','bcfg','acdfg','acdefg','abc','abcdefg','abcdfg'];
function syncScore(){
  const source=document.querySelector('[data-bind="qst-score-value"]');
  const raw=source?.textContent.trim();const value=raw&&/\d/.test(raw)?Number(raw.replace(/[^\d.-]/g,'')):null;
  const valid=value!==null&&Number.isFinite(value)&&value>=0;
  const digits=valid?String(Math.round(value)).padStart(2,'0').padStart(3,' '):'---';
  const svg=score.querySelector('.concept-degen-digits');
  while(svg.children.length<digits.length){const group=svg.firstElementChild.cloneNode(true);group.dataset.digit=String(svg.children.length);group.setAttribute('transform',`translate(${svg.children.length*38} 0)`);svg.append(group);}
  while(svg.children.length>digits.length)svg.lastElementChild.remove();
  svg.setAttribute('viewBox',`-5 0 ${digits.length*38} 60`);
  score.dataset.scoreTier=valid?degenScoreLootTier(value):'white';score.setAttribute('aria-label',valid?`Degen rating: ${value}%`:'Degen rating loading');
  [...svg.children].forEach((group,i)=>{group.style.visibility=digits[i]===' '?'hidden':'';const lit=digits[i]==='-'?'g':digits[i]===' '?'':segments[Number(digits[i])];group.querySelectorAll('[data-segment]').forEach(segment=>segment.classList.toggle('is-lit',lit.includes(segment.dataset.segment)));});
}
