function syncPool(){
  const text=key=>pool.querySelector(`[data-el="${key}"]`)?.textContent.trim()||'—';
  const jackpot=pool.querySelector('.pool-progress')?.dataset.mode==='jackpot';
  const level=jackpot?text('pool-jackpot-level'):text('pool-name').match(/LEVEL (\d+)/)?.[1]||'—';
  const live=get('app.livePools'),game=get('app.gameState');
  const wei=jackpot?(live?.components?.currentWei??game?.prizePools?.currentPrizePool):(live?.components?.nextWei??game?.prizePools?.nextPrizePool);
  let amount='—';try{if(wei!=null){const n=Number(displayEth(BigInt(wei)));amount=n.toLocaleString('en-US',{maximumFractionDigits:0});}}catch{}
  const scale=syncVerticalPoolScale(pool,thermo,{jackpot});
  const percent=scale.percent;
  const thresholdTitle=scale.ready?(scale.over?'':scale.growthTitle):scale.targetTitle;
  thermo.querySelector('.concept-level>small').textContent='LEVEL';
  thermo.querySelector('.concept-level strong').textContent=level;
  let dayLabel=thermo.querySelector('.site-pool-day');
  if(!dayLabel){dayLabel=document.createElement('span');dayLabel.className='site-pool-day';dayLabel.innerHTML='DAY <b></b>';thermo.querySelector('.concept-level').append(dayLabel);}
  dayLabel.querySelector('b').textContent=scale.day??'—';
  thermo.querySelector('.concept-pool-amount strong').textContent=amount;
  thermo.querySelector('.concept-pool-amount>span').textContent='ETH';
  thermo.querySelector('.concept-track').style.setProperty('--site-pool-fill',`${Math.max(0,Math.min(100,percent))}%`);
  const days=!jackpot&&!scale.ready,track=thermo.querySelector('.concept-track');
  track.setAttribute('aria-valuemax','100');
  track.setAttribute('aria-valuenow',String(percent));
  const description=`Level ${level}, day ${scale.day??'loading'}; prize pool ${amount} ETH${days?`; ${scale.day??'unknown'} of 30 days toward target`:scale.ready?'; target met, expanded pool scale':''}${!jackpot&&thresholdTitle?`; ${thresholdTitle}`:''}`;
  thermo.title=description;thermo.setAttribute('aria-label',description);track.setAttribute('aria-valuetext',description);
}
