let fitting=false;
function fit(){
  fitting=false;if(!desktop.matches)return;
  if(document.body.dataset.desktopPage==='games'){
    document.body.style.setProperty('--hub-width',`${main.clientWidth}px`);
    const play=main.querySelector('.play-grid'),style=getComputedStyle(main);
    const height=main.clientHeight-headline.getBoundingClientRect().height-document.querySelector('.info-rail').getBoundingClientRect().height
      -(parseFloat(style.paddingTop)||0)-(parseFloat(style.paddingBottom)||0)-(parseFloat(style.rowGap)||0)-2;
    play.style.setProperty('--site-games-height',`${Math.max(368,Math.floor(height))}px`);
    return;
  }
  if(document.body.dataset.desktopPage!=='daily')return;
  let low=640,high=Math.min(1160,main.clientWidth);
  for(let i=0;i<10;i++){
    const width=(low+high)/2;document.body.style.setProperty('--hub-width',`${width}px`);
    const children=[...main.children].filter(el=>{const css=getComputedStyle(el);return css.display!=='none'&&!['fixed','absolute'].includes(css.position);});
    const css=getComputedStyle(main);
    const used=children.reduce((sum,el)=>{const style=getComputedStyle(el);return sum+el.getBoundingClientRect().height+(parseFloat(style.marginTop)||0)+(parseFloat(style.marginBottom)||0);},0)
      +Math.max(0,children.length-1)*(parseFloat(css.rowGap)||0)+(parseFloat(css.paddingTop)||0)+(parseFloat(css.paddingBottom)||0);
    if(used<=main.clientHeight-2)low=width;else high=width;
  }
  document.body.style.setProperty('--hub-width',`${Math.floor(low)}px`);
}
const queueFit=()=>{if(!fitting){fitting=true;requestAnimationFrame(fit);}};
const fitObserver=new ResizeObserver(queueFit);fitObserver.observe(main);fitObserver.observe(document.querySelector('.jackpot-hero'));fitObserver.observe(headline);window.addEventListener('resize',queueFit);document.fonts.ready.then(queueFit);document.addEventListener('load',queueFit,true);document.addEventListener('desktop-sections:change',queueFit);queueFit();
